create table bị dị ứng(StuID INTEGER,Allergy VARCHAR(20),FOREIGN KEY(StuID) REFERENCES Student(StuID),FOREIGN KEY(Allergy) REFERENCES loại dị ứng(Allergy)) ; 
create table Student(StuID INTEGER PRIMARY KEY,LName VARCHAR(12),Fname VARCHAR(12),Age INTEGER,Sex VARCHAR(1),Major INTEGER,Advisor INTEGER,mã thành phố VARCHAR(3)) ;

